function sum(a, b) {
  console.log(this.n + a + b);
}
const step = sum.bind({ n: 1 }, 2).bind({ n: 9 }, 3);
step(4);

const box = {
  n: 1,
  run() {
    const read = () => console.log(this.n);
    read.call({ n: 2 });
    read.apply({ n: 3 });
  },
};
box.run();

function ObjectBox() {
  this.n = 1;
  return { n: 2 };
}
function PrimitiveBox() {
  this.n = 1;
  return 3;
}
console.log(new ObjectBox().n);
console.log(new PrimitiveBox().n);

function show() {
  'use strict';
  if (this == null) {
    console.log(1);
    return;
  }
  console.log(this + 2);
}
show.call(null);
show.call(3);

const box = {
  n: 1,
  get next() {
    return this.n + 1;
  },
};
console.log(box.next);
const getNext = Object.getOwnPropertyDescriptor(box, 'next').get;
console.log(getNext.call({ n: 4 }));

function add(extra = this.n) {
  console.log(this.n + extra);
}
add.call({ n: 1 });
add.call({ n: 2 }, 3);

function show(extra) {
  console.log(this.n + extra);
}
Function.prototype.call.call(show, { n: 1 }, 2);
Reflect.apply(show, { n: 4 }, [5]);
